const input = $input.first().json || {};

function getByPath(obj, path) {
  if (!path) return undefined;
  return path.split(".").reduce((acc, key) => {
    if (acc && Object.prototype.hasOwnProperty.call(acc, key)) {
      return acc[key];
    }
    return undefined;
  }, obj);
}

function safe(value) {
  return value === undefined || value === null || value === "" ? "-" : String(value);
}

function makeApprovalId(eventId) {
  const base = eventId || "unknown_event";
  const suffix = Date.now().toString(36);
  return `appr_${base}_${suffix}`;
}

function fail({ code, message, details = [] }) {
  return [
    {
      json: {
        success: false,
        component_id: "C2-O",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        approval: {
          approval_id: null,
          status: "failed",
          approval_type: input.config?.approval_type || null,
          approval_title: input.config?.approval_title || null,
          reviewer_email: input.config?.reviewer_email || null,
          allowed_actions: input.config?.approval_actions || [],
          context: {}
        },
        source_result: input.input || {},
        notification_payload: null,
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty."
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object."
  });
}

const source = input.input;
const config = input.config || {};

if (source.success !== true) {
  return fail({
    code: "UPSTREAM_ACTION_FAILED",
    message: "C2-O will not create approval request when upstream action failed.",
    details: [
      {
        upstream_component: source.component_id || null,
        upstream_error: source.error || null
      }
    ]
  });
}

if (source.next_action !== "request_approval") {
  return fail({
    code: "APPROVAL_NOT_REQUESTED",
    message: "source.next_action is not request_approval.",
    details: [{ next_action: source.next_action || null }]
  });
}

if (!config.approval_type) {
  return fail({
    code: "MISSING_APPROVAL_TYPE",
    message: "config.approval_type is required."
  });
}

if (!config.approval_title) {
  return fail({
    code: "MISSING_APPROVAL_TITLE",
    message: "config.approval_title is required."
  });
}

if (!config.reviewer_email) {
  return fail({
    code: "MISSING_REVIEWER_EMAIL",
    message: "config.reviewer_email is required."
  });
}

const actions = Array.isArray(config.approval_actions) && config.approval_actions.length > 0
  ? config.approval_actions
  : ["approve", "reject"];

const contextFields = Array.isArray(config.approval_context_fields)
  ? config.approval_context_fields
  : [];

const approvalContext = {};

for (const path of contextFields) {
  approvalContext[path] = getByPath(source, path) ?? null;
}

const approvalId = makeApprovalId(source.event_id);

const approvalText = [
  `Approval request`,
  ``,
  `Approval ID: ${approvalId}`,
  `Title: ${safe(config.approval_title)}`,
  `Type: ${safe(config.approval_type)}`,
  `Reviewer: ${safe(config.reviewer_email)}`,
  `Event ID: ${safe(source.event_id)}`,
  `Event Type: ${safe(source.event_type)}`,
  `Source Component: ${safe(source.component_id)}`,
  ``,
  `Context`,
  ...Object.entries(approvalContext).map(([key, value]) => `${key}: ${safe(value)}`),
  ``,
  `Allowed Actions: ${actions.join(", ")}`,
  ``,
  `Approval response capture is not implemented in C2-O v1. Use C2-O2 or a manual control table for live approval capture.`
].join("\n");

return [
  {
    json: {
      success: true,
      component_id: "C2-O",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: source.event_type || null,
      approval: {
        approval_id: approvalId,
        status: "pending",
        approval_type: config.approval_type,
        approval_title: config.approval_title,
        reviewer_email: config.reviewer_email,
        allowed_actions: actions,
        context: approvalContext,
        requested_at: new Date().toISOString()
      },
      source_result: source,
      notification_payload: {
        channel: "email",
        to: config.reviewer_email,
        subject: `Approval required: ${config.approval_title}`,
        text: approvalText
      },
      error: null,
      next_action: config.default_next_action || "notify_reviewer"
    }
  }
];
